1	// Provisioning creates things in someone's Cloudflare account and reads back where they
2	// landed, and neither half can be exercised here — there is no account to run against. What
3	// *can* be held is the reasoning either half does before it acts: when the provisioner is
4	// allowed to create, and how an origin is read out of what a deploy printed.
5	//
6	// The refusals are the point. Creating a resource because a token scope stopped us asking
7	// about it, or creating a Vectorize index on a guessed dimension count, are both mistakes
8	// nobody sees until much later — an index's dimensions cannot be changed afterwards.
9	import test from 'node:test';
10	import assert from 'node:assert/strict';
11	import {
12	  ALLOWED,
13	  PAGES_PROJECT,
14	  PLACEHOLDER_DATABASE_ID,
15	  RESOURCES,
16	  VECTORIZE_INDEX,
17	  assertSafe,
18	  decide,
19	  firstUsefulLine,
20	  missing,
21	  present,
22	  unknown,
23	  withDatabaseId,
24	} from '../tools/cloudflare.ts';
25	import { deployedSite, deployedWorker, overrideFrom, projectSite } from '../tools/origins.ts';
26	
27	const resource = (name: string) => {
28	  const found = RESOURCES.find((candidate) => candidate.name === name);
29	  assert.ok(found, `no resource named ${name} — has the table changed shape?`);
30	  return found;
31	};
32	
33	test('a resource Cloudflare says is absent is created', () => {
34	  const bucket = resource('hitbut-raw');
35	  assert.deepEqual(decide(bucket, missing('hitbut-raw is not in the list')).act, 'create');
36	});
37	
38	test('a resource that is already there is left alone', () => {
39	  assert.equal(decide(resource('hitbut-raw'), present('found')).act, 'leave');
40	});
41	
42	test('a question that could not be asked is never read as an absence', () => {
43	  const decision = decide(resource('hitbut-raw'), unknown('`wrangler r2 bucket list` failed — bad token'));
44	  assert.equal(decision.act, 'leave');
45	  assert.match(decision.why, /could not be asked/);
46	});
47	
48	test('the Vectorize index is not created on a guessed dimension count', () => {
49	  assert.equal(process.env.VECTORIZE_DIMENSIONS, undefined, 'this test states what happens when it is unset');
50	  const decision = decide(resource(VECTORIZE_INDEX), missing('not in the list'));
51	  assert.equal(decision.act, 'leave');
52	  assert.match(decision.why, /dimensions at creation/);
53	});
54	
55	test('every create command names the resource the check looks for', () => {
56	  for (const candidate of RESOURCES) {
57	    assert.ok(
58	      candidate.create.includes(candidate.name),
59	      `${candidate.label} would create something other than what the preflight looks for`,
60	    );
61	  }
62	});
63	
64	test('creating the Pages project cannot stop to ask a question', () => {
65	  // A prompt on a runner is a hang, not a failure. --production-branch is what removes it.
66	  assert.ok(resource(PAGES_PROJECT).create.includes('--production-branch'));
67	});
68	
69	// The token provisioning holds can erase the corpus and the raw bucket. What follows is the
70	// closed door: these tools list, create and deploy, and every other command is refused
71	// before a process is started — including one a later edit adds without meaning to.
72	for (const argv of [
73	  ['d1', 'delete', 'hitbut-corpus'],
74	  ['d1', 'execute', 'hitbut-corpus', '--command', 'DROP TABLE utterances'],
75	  ['r2', 'bucket', 'delete', 'hitbut-raw'],
76	  ['r2', 'object', 'delete', 'hitbut-raw/anything'],
77	  ['vectorize', 'delete', VECTORIZE_INDEX],
78	  ['pages', 'project', 'delete', PAGES_PROJECT],
79	  ['delete', '--name', 'hitbut-api'],
80	  ['rollback'],
81	  ['secret', 'delete', 'ANYTHING'],
82	]) {
83	  test(`\`wrangler ${argv.join(' ')}\` does not run`, () => {
84	    assert.throws(() => assertSafe(argv), /refusing to run/);
85	  });
86	}
87	
88	test('the commands that are allowed are only lists, creates and deploys', () => {
89	  for (const command of ALLOWED) {
90	    assert.doesNotThrow(() => assertSafe([...command]));
91	    assert.match(
92	      command.join(' '),
93	      /(^| )(list|create|deploy)$/,
94	      `"${command.join(' ')}" is allowed but is not a list, a create or a deploy`,
95	    );
96	  }
97	});
98	
99	test('every command the tools actually run is one of the allowed ones', () => {
100	  for (const resource of RESOURCES) {
101	    assert.doesNotThrow(() => assertSafe(resource.list), `\`wrangler ${resource.list.join(' ')}\` would be refused`);
102	    assert.doesNotThrow(() => assertSafe(resource.create), `\`wrangler ${resource.create.join(' ')}\` would be refused`);
103	  }
104	  assert.doesNotThrow(() => assertSafe(['deploy']));
105	  assert.doesNotThrow(() => assertSafe(['pages', 'deploy', 'src/frontend/dist', '--project-name', PAGES_PROJECT]));
106	  assert.doesNotThrow(() => assertSafe(['pages', 'project', 'list', '--json']));
107	});
108	
109	test('a real database id is never rewritten, whatever the account says', () => {
110	  const pinned = 'database_id = "8f14e45f-ce0a-4b1f-9a3c-2d5b7c1e0a99"';
111	  assert.equal(withDatabaseId(pinned, 'a-different-database'), pinned);
112	});
113	
114	test('the placeholder is the only id that gets replaced', () => {
115	  const placeholder = `database_id = "${PLACEHOLDER_DATABASE_ID}"`;
116	  assert.equal(withDatabaseId(placeholder, 'the-real-one'), 'database_id = "the-real-one"');
117	  assert.throws(() => withDatabaseId('name = "hitbut-api"', 'the-real-one'), /changed shape/);
118	});
119	
120	test("the Worker's origin is read out of what wrangler printed", () => {
121	  const output = [
122	    'Total Upload: 92.41 KiB / gzip: 20.11 KiB',
123	    'Uploaded hitbut-api (3.90 sec)',
124	    'Deployed hitbut-api triggers (0.31 sec)',
125	    '  https://hitbut-api.missingbulb.workers.dev',
126	    'Current Version ID: 7f6b…',
127	  ].join('\n');
128	  assert.equal(deployedWorker(output)?.url, 'https://hitbut-api.missingbulb.workers.dev');
129	});
130	
131	test("colour codes do not hide the Worker's origin", () => {
132	  const output = `[32m  https://hitbut-api.missingbulb.workers.dev[0m`;
133	  assert.equal(deployedWorker(output)?.url, 'https://hitbut-api.missingbulb.workers.dev');
134	});
135	
136	test('a deploy that printed no origin is a failure, not an empty string', () => {
137	  assert.equal(deployedWorker('Uploaded hitbut-api (3.90 sec)'), null);
138	});
139	
140	test('a repository variable wins over what was read back', () => {
141	  assert.equal(overrideFrom('API_ORIGIN', 'https://api.hitbut.example/')?.url, 'https://api.hitbut.example');
142	  assert.equal(overrideFrom('API_ORIGIN', '  '), null);
143	  assert.equal(overrideFrom('API_ORIGIN', undefined), null);
144	});
145	
146	test("the site's origin is the project's own host, not the deployment's alias", () => {
147	  const listed = JSON.stringify([{ name: 'other', subdomain: 'other.pages.dev' }, { name: PAGES_PROJECT, subdomain: 'hitbut.pages.dev' }]);
148	  assert.equal(projectSite(listed, PAGES_PROJECT)?.url, 'https://hitbut.pages.dev');
149	});
150	
151	test("wrangler's own warnings do not get read as the list", () => {
152	  // `--json` output arrives with the banner and any warnings around it, and `[WARNING]` is a
153	  // bracket too — the first `[` in the output is routinely not the list.
154	  const noisy = [
155	    ' ⛅️ wrangler 4.125.0',
156	    '▲ [WARNING] Proxy environment variables detected.',
157	    JSON.stringify([{ name: PAGES_PROJECT, subdomain: 'hitbut.pages.dev' }]),
158	  ].join('\n');
159	  assert.equal(projectSite(noisy, PAGES_PROJECT)?.url, 'https://hitbut.pages.dev');
160	});
161	
162	test('a Pages listing that cannot be read is not an origin', () => {
163	  assert.equal(projectSite('Authentication error', PAGES_PROJECT), null);
164	  assert.equal(projectSite(JSON.stringify([{ name: 'somebody-else' }]), PAGES_PROJECT), null);
165	});
166	
167	test("falling back to the deployment URL strips the per-deployment label", () => {
168	  const output = '✨ Deployment complete! Take a peek over at https://a1b2c3d4.hitbut.pages.dev';
169	  assert.equal(deployedSite(output, PAGES_PROJECT)?.url, 'https://hitbut.pages.dev');
170	});
