1	// Where a deployed half of the product can be reached, worked out from what the deploy
2	// itself said. Pure: given text, it returns an origin, so the reading can be tested without
3	// an account. Doing the deploy is `deploy.ts`.
4	import { jsonArrayIn, stripAnsi } from './cloudflare.ts';
5	
6	/** Every origin carries how it was found, because "derived" and "overridden" fail differently. */
7	export type Origin = { url: string; how: string };
8	
9	/** A custom domain in front of either half is the one thing that cannot be derived. */
10	export const overrideFrom = (name: string, value: string | undefined): Origin | null => {
11	  const trimmed = value?.trim().replace(/\/+$/, '');
12	  return trimmed ? { url: trimmed, how: `the ${name} repository variable` } : null;
