24	/**
25	 * The Pages project's own production hostname, out of `pages project list --json`. Preferred
26	 * over the deploy output, which carries the per-deployment alias — a URL that answers, but
27	 * is not where anyone reads the site.
28	 */
29	export const projectSite = (json: string, project: string): Origin | null => {
30	  const projects = jsonArrayIn<{ name?: string; subdomain?: string; domains?: string[] }>(json);
31	  const found = projects?.find((candidate) => candidate.name === project);
32	  const host = found?.subdomain ?? found?.domains?.[0];
33	  return host ? { url: `https://${host.replace(/^https?:\/\//, '')}`, how: "the Pages project's own subdomain" } : null;
