1	// Creates whatever production is missing. The counterpart to the preflight: same table of
2	// resources, same question asked of Cloudflare — but where the preflight reports a `MISS`,
3	// this creates the thing.
4	//
5	// Every resource hitbut needs is one non-interactive `wrangler … create`, so none of this
6	// needs the dashboard; what needs a human is the account, the API token and the decision to
7	// spend money in that account, which is why this runs from a `workflow_dispatch` rather than
8	// on its own.
9	//
10	// Three rules it will not break:
11	//
12	//   * **It cannot destroy anything.** The runner is closed by default — it lists, it creates,
13	//     it deploys — so no command that removes a database, a bucket, an index or their
14	//     contents will run, whatever a later edit here asks for. The token it holds could do
15	//     all of that; this is what stops it.
16	//   * **It creates only on a confirmed absence.** A resource we could not ask about (a token
17	//     scope, a renamed command, a refused network) is left alone and reported, because
18	//     creating a second copy of something that is already there is worse than stopping.
19	//   * **It never guesses a shape that cannot be changed later.** A Vectorize index fixes its
20	//     dimension count at creation, so without an explicit `VECTORIZE_DIMENSIONS` it declines
21	//     rather than pick one.
22	//
23	// Usage: `npm run provision` (creates), `npm run provision -- --dry-run` (says what it would).
24	import { readFileSync, writeFileSync } from 'node:fs';
25	import { fileURLToPath } from 'node:url';
26	import {
27	  D1_DATABASE,
28	  PLACEHOLDER_DATABASE_ID,
29	  RESOURCES,
30	  databaseIdIn,
31	  decide,
32	  jsonArrayIn,
33	  look,
34	  withDatabaseId,
35	  wrangler,
36	} from './cloudflare.ts';
37	
38	const WRANGLER_TOML = fileURLToPath(new URL('../../wrangler.toml', import.meta.url));
39	const dryRun = process.argv.includes('--dry-run');
40	
41	type Outcome = 'already there' | 'created' | 'would create' | 'declined' | 'failed';
42	const results: { label: string; outcome: Outcome; detail: string }[] = [];
43	const record = (label: string, outcome: Outcome, detail = '') => {
44	  results.push({ label, outcome, detail });
45	  console.log(`  [${outcome.padEnd(12)}] ${label}${detail ? ` — ${detail}` : ''}`);
46	};
47	
48	console.log('\nhitbut provision — creates what production is missing, and nothing else\n');
49	if (dryRun) console.log('  (dry run: nothing will be created)\n');
50	
51	for (const resource of RESOURCES) {
52	  const state = look(resource);
53	  const decision = decide(resource, state);
54	  if (decision.act === 'leave') {
55	    record(resource.label, state.state === 'present' ? 'already there' : 'declined', decision.why);
56	    continue;
57	  }
58	  if (dryRun) {
59	    record(resource.label, 'would create', decision.why);
60	    continue;
61	  }
62	  const run = wrangler(resource.create);
63	  record(resource.label, run.ok ? 'created' : 'failed', run.ok ? '' : run.reason);
64	}
65	
66	/**
67	 * The one piece of production that lives in the repo rather than in the account: D1 hands
68	 * out the id when it creates the database, and `wrangler deploy` reads it from the committed
69	 * config. Resolving it from the database's own name keeps this true whoever created it —
70	 * a run against an account provisioned by hand writes the same line.
71	 */
72	function pinDatabaseId(): void {
73	  const toml = readFileSync(WRANGLER_TOML, 'utf8');
74	  const pinned = databaseIdIn(toml);
75	  if (pinned && pinned !== PLACEHOLDER_DATABASE_ID) {
76	    record('wrangler.toml database_id', 'already there', `pinned to ${pinned}`);
77	    return;
78	  }
79	
80	  const listed = wrangler(['d1', 'list', '--json'], 90_000);
81	  if (!listed.ok) {
82	    record('wrangler.toml database_id', 'declined', `could not read the id back — ${listed.reason}`);
83	    return;
84	  }
85	  const databases = jsonArrayIn<{ uuid?: string; name?: string }>(listed.output);
86	  if (!databases) {
87	    record('wrangler.toml database_id', 'failed', '`d1 list --json` printed no list to read');
88	    return;
89	  }
90	  const uuid = databases.find((database) => database.name === D1_DATABASE)?.uuid;
91	  if (!uuid) {
92	    record('wrangler.toml database_id', 'declined', `${D1_DATABASE} is not in the account's list yet`);
93	    return;
94	  }
95	  if (dryRun) {
96	    record('wrangler.toml database_id', 'would create', `would pin ${uuid}`);
97	    return;
98	  }
99	  writeFileSync(WRANGLER_TOML, withDatabaseId(toml, uuid));
100	  record('wrangler.toml database_id', 'created', `pinned to ${uuid} — commit this`);
101	}
102	
103	pinDatabaseId();
104	
105	const failed = results.filter((result) => result.outcome === 'failed');
106	const declined = results.filter((result) => result.outcome === 'declined');
107	
108	console.log('');
109	if (declined.length) {
110	  console.log(
111	    `${declined.length} item(s) declined. Declining is deliberate: an unanswered question or an ` +
112	      'undecided shape is not the same as an absent resource, and creating on either is the mistake ' +
113	      'this refuses to make.',
114	  );
115	}
116	if (failed.length) {
117	  console.log(`\nFailed: ${failed.map((result) => result.label).join(', ')}`);
118	  process.exit(1);
119	}
120	console.log('\nRun the preflight to see production as it now stands.\n');

1	// Does production exist yet? Answers that question and nothing else — it creates nothing,
2	// changes nothing, and is safe to run any number of times. What production is made of, and
3	// how each piece is asked about, is `cloudflare.ts`; this file is the report.
4	//
5	// Two jobs. Before the first deploy it turns "did I do every step?" into a green check —
6	// and every `MISS` it reports is something `npm run provision` creates. After the first
7	// deploy it is the first thing to run when a deploy fails, because most deploy failures are
8	// a resource or a secret that is not there.
9	import { readFileSync } from 'node:fs';
10	import { fileURLToPath } from 'node:url';
11	import {
12	  D1_DATABASE,
13	  PLACEHOLDER_DATABASE_ID,
14	  RESOURCES,
15	  databaseIdIn,
16	  look,
17	  missing,
18	  present,
19	  unknown,
20	  type Result,
21	} from './cloudflare.ts';
22	
23	const WRANGLER_TOML = fileURLToPath(new URL('../../wrangler.toml', import.meta.url));
24	const SECRETS_SETTINGS = 'https://github.com/missingbulb/hitbut/settings/secrets/actions';
25	
26	type Check = {
27	  label: string;
28	  /** A failing optional check reports but does not fail the run — not everything is built yet. */
29	  required: boolean;
30	  why: string;
31	  /** Where to go to fix it: a dashboard page, a settings page, or the command that does it. */
32	  fix: string;
33	  run: () => Result;
34	};
35	
36	function fromEnvironment(name: string): Result {
37	  const value = process.env[name];
38	  return value ? present(`set (${value.length} characters)`) : missing('not set');
39	}
40	
41	function databaseIdPinned(): Result {
42	  const id = databaseIdIn(readFileSync(WRANGLER_TOML, 'utf8'));
43	  if (!id) return unknown('no database_id line in wrangler.toml — has the config changed shape?');
44	  return id === PLACEHOLDER_DATABASE_ID
45	    ? missing('still the all-zeros placeholder')
46	    : present(`pinned to ${id}`);
47	}
48	
49	const CHECKS: Check[] = [
50	  {
51	    label: 'secret CLOUDFLARE_ACCOUNT_ID',
52	    required: true,
53	    why: 'nothing deploys without it, and every check below needs it',
54	    fix: `paste it at ${SECRETS_SETTINGS}`,
55	    run: () => fromEnvironment('CLOUDFLARE_ACCOUNT_ID'),
56	  },
57	  {
58	    label: 'secret CLOUDFLARE_API_TOKEN',
59	    required: true,
60	    why: 'nothing deploys without it, and every check below needs it',
61	    fix: `paste it at ${SECRETS_SETTINGS}`,
62	    run: () => fromEnvironment('CLOUDFLARE_API_TOKEN'),
63	  },
64	  {
65	    label: 'wrangler.toml database_id',
66	    required: true,
67	    why: 'the migrate step runs against this id; the placeholder is not a database',
68	    fix: 'the provision workflow reads the real id back and commits it',
69	    run: databaseIdPinned,
70	  },
71	  ...RESOURCES.map((resource) => ({
72	    label: resource.label,
73	    required: resource.required,
74	    why: resource.why,
75	    fix: `\`npm run provision\` creates it — or by hand at ${resource.dashboard(process.env.CLOUDFLARE_ACCOUNT_ID)}`,
76	    run: () => look(resource),
77	  })),
78	];
79	
80	const MARK: Record<Result['state'], string> = { present: 'ok  ', missing: 'MISS', unknown: '??  ' };
81	
82	const results = CHECKS.map((check) => ({ check, result: check.run() }));
83	
84	console.log('\nhitbut preflight — reads production, changes nothing\n');
85	for (const { check, result } of results) {
86	  console.log(`  [${MARK[result.state]}] ${check.label}`);
87	  console.log(`         ${result.detail}`);
88	  if (result.state !== 'present') {
89	    console.log(`         why it matters: ${check.why}`);
90	    console.log(`         how to fix it:  ${check.fix}`);
91	  }
92	}
93	
94	const blocking = results.filter(({ check, result }) => check.required && result.state !== 'present');
95	const advisory = results.filter(({ check, result }) => !check.required && result.state !== 'present');
96	const unanswered = results.filter(({ result }) => result.state === 'unknown');
97	
98	console.log('');
99	if (advisory.length) console.log(`${advisory.length} optional item(s) not ready — expected until the work that needs them lands.`);
100	if (unanswered.length) {
101	  console.log(
102	    `${unanswered.length} check(s) could not be answered. That is not the same as the resource being absent — ` +
103	      'fix the question (token scope, command name, network) before creating anything. The provisioner ' +
104	      'refuses to create on an unanswered question for exactly this reason.',
105	  );
106	}
107	if (blocking.length) {
108	  console.log(`\nNot ready to deploy: ${blocking.map(({ check }) => check.label).join(', ')}`);
109	  console.log(`Everything above that says MISS is created by the *provision* workflow; ${D1_DATABASE} included.`);
110	  console.log('The checklist these come from is issue #27.\n');
111	  process.exit(1);
112	}
113	console.log('\nEverything required is in place.\n');

